        static Label Caption(string text){return new Label{Text=text,AutoSize=true,Margin=new Padding(5,7,3,3)};}static void Combo(ComboBox c,string name,int width){c.Name=name;c.DropDownStyle=ComboBoxStyle.DropDownList;c.Width=width;c.ForeColor=SystemColors.WindowText;c.BackColor=SystemColors.Window;}static Button Button(string name,string text){return new Button{Name=name,Text=text,AutoSize=true,MinimumSize=new Size(78,32),ForeColor=SystemColors.ControlText,BackColor=SystemColors.Control,UseVisualStyleBackColor=true};}
        void Pending(){if(Snapshot==null||closing||IsDisposed||Disposing)return;pending.Text=appliedMode==modes[mode.SelectedIndex]&&appliedConfigured==configured.SelectedIndex+1&&appliedDifficulty==(int)difficulty.Value&&appliedSeed==(uint)seed.SelectedItem?"Controls match the applied trace.":"Selection pending. Generate applies controls; Reset keeps the applied setup.";}
        static byte[] Roster(int count){var p=new byte[176];for(int n=0;n<p.Length;n++)p[n]=(byte)(0x6d^(n%11));for(int n=0;n<4;n++)BitConverter.GetBytes(count==2&&n==0||count==3&&n==1?1:2).CopyTo(p,n*44);return p;}
        void LoadCopy(bool reset){if(closing||IsDisposed||Disposing)return;if(!reset||Snapshot==null){appliedMode=modes[mode.SelectedIndex];appliedConfigured=configured.SelectedIndex+1;appliedDifficulty=(int)difficulty.Value;appliedSeed=(uint)seed.SelectedItem;}Snapshot=PracticeCpuPresetSelection.Evaluate(presets,Roster(appliedConfigured),appliedConfigured,appliedMode,appliedDifficulty,appliedSeed);syncing=true;try{trace.Rows.Clear();int ordinal=0;foreach(var q in Snapshot.Requests)trace.Rows.Add(++ordinal,q.Owner,q.ConstructorKind,q.TemplateSlot,q.RandomDraws);if(trace.Rows.Count>0)trace.CurrentCell=trace.Rows[0].Cells[0];}finally{syncing=false;}summary.Text="Applied source mode "+appliedMode+" · configured records "+appliedConfigured+" · raw difficulty "+appliedDifficulty+" · seed "+appliedSeed+"\r\nRequests: "+Snapshot.Requests.Count+" · derived RNG draws: "+Snapshot.RandomDraws+" · final RNG: 0x"+Snapshot.FinalRandomState.ToString("X8")+"\r\n40 loaded slots / 16 tag-10 candidates. Actual constructor and placement are not executed.";Pending();Inspect();}
        void Inspect(){if(closing||IsDisposed||Disposing||Snapshot==null)return;var text=new StringBuilder();text.Append("Source callback order is grouped by ascending zero-based owner. Only participant kind 2 is admitted.\r\n");if(trace.CurrentRow!=null&&trace.CurrentRow.Index>=0&&trace.CurrentRow.Index<Snapshot.Requests.Count){var q=Snapshot.Requests[trace.CurrentRow.Index];text.AppendFormat("Viewing request {0}: owner {1}; constructor kind {2}; preset slot {3}; derived draws {4}.\r\n",trace.CurrentRow.Index+1,q.Owner,q.ConstructorKind,q.TemplateSlot,q.RandomDraws);byte[] table=presets.CopyTable();text.AppendFormat("Selected table record tag {0}, raw owner byte {1}. First ten raw cell values:\r\n",table[q.TemplateSlot*402],table[q.TemplateSlot*402+1]);for(int n=0;n<10;n++)text.Append(BitConverter.ToInt32(table,q.TemplateSlot*402+2+n*4)+" ");text.Append("\r\n");}else text.Append(appliedMode==4?"No requests: the supplied signed difficulty+2 budget is not positive.\r\n":"No requests: this mode takes the source load/refresh branch and skips the construction-request loop.\r\n");text.Append("\r\n288 original contexts match request order, final RNG and complete participant/preset tables.\r\nDraw counts are model-derived; native final states and selected slots match.\r\nConstructor callback records requests and preserves RNG. No units, placement, movement or live AI run.\r\nA modern 4,096-draw guard rejects nonterminating study inputs rather than hanging.");details.Text=text.ToString();}
        internal bool StudyKey(Keys key,bool down){if(key!=Keys.Enter&&key!=Keys.Escape)return false;if(!down){held.Remove(key);return true;}if(!held.Add(key))return true;if(key==Keys.Escape)Close();else LoadCopy(false);return true;}protected override bool ProcessCmdKey(ref Message message,Keys keyData){if(StudyKey(keyData&Keys.KeyCode,true))return true;return base.ProcessCmdKey(ref message,keyData);}protected override void OnKeyUp(KeyEventArgs e){if(StudyKey(e.KeyCode,false))e.Handled=true;base.OnKeyUp(e);}protected override void OnActivated(EventArgs e){base.OnActivated(e);foreach(Keys key in new[]{Keys.Enter,Keys.Escape})if((GetAsyncKeyState((int)key)&0x8000)!=0)held.Add(key);}protected override void OnFormClosing(FormClosingEventArgs e){closing=true;base.OnFormClosing(e);}protected override void Dispose(bool disposing){if(disposing){closing=true;mono.Dispose();}base.Dispose(disposing);}
